insert into public.courses (slug,title,summary,level,objectives,certificate_title,final_task,prerequisite_slug,visible,sort,needs_review) values ('beginner-design-basics','Design basics (Beginner)','Open a template, make it yours and download it. No experience needed.','Beginner',array['Open a template and change the words','Colours and fonts','Replace a photo','Add shapes and elements','Pages and sizes','Download and share']::text[],'Beginner Designer — Magical Touch Design Tutorials','Design a social media post or flyer for a real or made-up business, using a template, your own text and one of your own photos.',null,true,1,true) on conflict (slug) do nothing;
insert into public.course_lessons (course_id,slug,title,tool,minutes,intro,steps,task,try_href,try_label,visible,sort,needs_review) select id,'open-a-template-and-change-the-words','Open a template and change the words','Templates & text',5,'Every design starts faster from a template. You will open one and replace its text.',array['Go to Templates and search for something you need, like “flyer”.','Click a template, then “Use this template”.','Double-click any text on the page to type your own words.','Press Esc or click an empty area when you are done.']::text[],'Open any template and change the headline to your own name or business.','/templates','Browse templates',true,1,true from public.courses where slug='beginner-design-basics' on conflict (course_id,slug) do nothing;
insert into public.course_lessons (course_id,slug,title,tool,minutes,intro,steps,task,try_href,try_label,visible,sort,needs_review) select id,'colours-and-fonts','Colours and fonts','Text toolbar & colour picker',6,'Colour and type set the mood of a design.',array['Click a text box once to select it.','Use the font menu at the top to try a different font.','Click the colour button and pick a new colour, or type a hex code.','Click an empty part of the page and change the Background colour.']::text[],'Change at least one font and two colours in your design.','/templates','Open a template',true,2,true from public.courses where slug='beginner-design-basics' on conflict (course_id,slug) do nothing;
insert into public.course_lessons (course_id,slug,title,tool,minutes,intro,steps,task,try_href,try_label,visible,sort,needs_review) select id,'replace-a-photo','Replace a photo','Upload & photo frames',5,'Templates come with sample photos — swap them for yours.',array['Open Upload on the left and upload a photo from your device.','Drag your photo onto a photo in the design to replace it.','Double-click the photo to move or zoom it inside its frame.']::text[],'Put one of your own photos into a template.','/templates','Open a template',true,3,true from public.courses where slug='beginner-design-basics' on conflict (course_id,slug) do nothing;
insert into public.course_lessons (course_id,slug,title,tool,minutes,intro,steps,task,try_href,try_label,visible,sort,needs_review) select id,'add-shapes-and-elements','Add shapes and elements','Elements panel',6,'Shapes, lines, icons and stickers add structure and personality.',array['Open Elements on the left.','Click a shape or icon to add it, then drag it into place.','Use the corner handles to resize; hold Shift to keep proportions.','Use Position → Bring forward / Send backward to change the order.']::text[],'Add a shape behind a heading to make it stand out.','/create','Start a blank design',true,4,true from public.courses where slug='beginner-design-basics' on conflict (course_id,slug) do nothing;
insert into public.course_lessons (course_id,slug,title,tool,minutes,intro,steps,task,try_href,try_label,visible,sort,needs_review) select id,'pages-and-sizes','Pages and sizes','Pages & Resize',5,'One design can have many pages and be resized for other uses.',array['Open Pages to add, duplicate or delete pages.','Use Resize at the top to turn a post into a story or an A4 flyer.','Choose “Resize a copy” to keep your original.']::text[],'Make a copy of your design in a second size (for example a story).','/create','Start a design',true,5,true from public.courses where slug='beginner-design-basics' on conflict (course_id,slug) do nothing;
insert into public.course_lessons (course_id,slug,title,tool,minutes,intro,steps,task,try_href,try_label,visible,sort,needs_review) select id,'download-and-share','Download and share','Export',4,'Get your design out of the editor in the right format.',array['Click Export at the top right.','Choose PNG or JPG for social media and WhatsApp, PDF for printing.','Pick the pages you want and click Download.']::text[],'Download your design as a PNG and as a PDF.','/templates','Open a design',true,6,true from public.courses where slug='beginner-design-basics' on conflict (course_id,slug) do nothing;
insert into public.courses (slug,title,summary,level,objectives,certificate_title,final_task,prerequisite_slug,visible,sort,needs_review) values ('intermediate-brand-and-photo','Brand, photos and print (Intermediate)','Layout, brand kits, photo editing and print-ready files.','Intermediate',array['Layers, alignment and spacing','Brand kit','Enhance and crop photos','Remove a background','Text effects','Print-ready PDF']::text[],'Intermediate Designer — Magical Touch Design Tutorials','Create a matching set for one brand: an Instagram post and a printable A4 flyer, both using your brand kit colours and fonts, with an edited photo.','beginner-design-basics',true,2,true) on conflict (slug) do nothing;
insert into public.course_lessons (course_id,slug,title,tool,minutes,intro,steps,task,try_href,try_label,visible,sort,needs_review) select id,'layers-alignment-and-spacing','Layers, alignment and spacing','Layers & arrange',8,'Clean layouts come from consistent alignment and spacing.',array['Open Layers to see everything on the page, top to bottom.','Select several items (Shift-click) and use Align and Distribute.','Lock items you do not want to move by accident.','Group items that belong together.']::text[],'Align a heading, text and button to the same left edge.','/templates','Open a template',true,1,true from public.courses where slug='intermediate-brand-and-photo' on conflict (course_id,slug) do nothing;
insert into public.course_lessons (course_id,slug,title,tool,minutes,intro,steps,task,try_href,try_label,visible,sort,needs_review) select id,'brand-kit','Brand kit','Brand panel',7,'Save your logo, colours and fonts once and apply them anywhere.',array['Open Brand on the left.','Add your logo, brand colours and heading / body fonts.','Start a New Design and tick “Use my brand”, or apply your colours and fonts from the Brand panel.']::text[],'Create a brand kit and apply it to a template.','/templates','Open a template',true,2,true from public.courses where slug='intermediate-brand-and-photo' on conflict (course_id,slug) do nothing;
insert into public.course_lessons (course_id,slug,title,tool,minutes,intro,steps,task,try_href,try_label,visible,sort,needs_review) select id,'enhance-and-crop-photos','Enhance and crop photos','Photo Studio (Simple)',8,'Fix light and colour, then crop for the right shape.',array['Open Photo Studio and upload a photo.','Click Auto enhance, then fine-tune Brightness, Contrast and Warmth.','Try a one-tap Look.','Crop to 4:5 for Instagram or Passport size for ID photos.']::text[],'Enhance one photo and crop it to 4:5.','/photo-studio','Open Photo Studio',true,3,true from public.courses where slug='intermediate-brand-and-photo' on conflict (course_id,slug) do nothing;
insert into public.course_lessons (course_id,slug,title,tool,minutes,intro,steps,task,try_href,try_label,visible,sort,needs_review) select id,'remove-a-background','Remove a background','Background remover',6,'Cut out a person or product and place it on a new background.',array['In Photo Studio choose Background → Remove background.','Refine the edge with the sliders and the Restore / Erase brushes.','Pick a new colour, or export PNG to keep it transparent.']::text[],'Cut out a product or person and put it on a brand colour.','/photo-studio','Open Photo Studio',true,4,true from public.courses where slug='intermediate-brand-and-photo' on conflict (course_id,slug) do nothing;
insert into public.course_lessons (course_id,slug,title,tool,minutes,intro,steps,task,try_href,try_label,visible,sort,needs_review) select id,'text-effects','Text effects','Effects',6,'Shadows, outlines, highlights and curved text — used with care.',array['Select a heading and open Effects.','Try Shadow, Outline, Highlight and Curve.','Keep body text plain so it stays easy to read.']::text[],'Give one heading an effect that improves readability on a photo.','/templates','Open a template',true,5,true from public.courses where slug='intermediate-brand-and-photo' on conflict (course_id,slug) do nothing;
insert into public.course_lessons (course_id,slug,title,tool,minutes,intro,steps,task,try_href,try_label,visible,sort,needs_review) select id,'print-ready-pdf','Print-ready PDF','Export → PDF for print shops',7,'Print shops need bleed, crop marks and CMYK colour.',array['Extend background colours and photos to the red bleed line.','Keep important text inside the safe area.','Export → PDF for print shops (CMYK with bleed and crop marks).','Open the PDF and check every page before you send it.']::text[],'Export a print PDF of an A4 flyer.','/templates','Open an A4 template',true,6,true from public.courses where slug='intermediate-brand-and-photo' on conflict (course_id,slug) do nothing;
insert into public.courses (slug,title,summary,level,objectives,certificate_title,final_task,prerequisite_slug,visible,sort,needs_review) values ('pro-photo-and-layout','Pro photo editing and layout (Pro)','Pro photo editing, multi-page documents and designing from a blank page.','Pro',array['Layers and blend modes','Selections and lasso','Retouching','Clean up: remove unwanted content and pages','Multi-page documents','Design from a blank page']::text[],'Pro Designer — Magical Touch Design Tutorials','Design a multi-page brochure or company profile (at least 4 pages) from a blank page, with consistent styles, at least one retouched photo and a clean print-ready export.','intermediate-brand-and-photo',true,3,true) on conflict (slug) do nothing;
insert into public.course_lessons (course_id,slug,title,tool,minutes,intro,steps,task,try_href,try_label,visible,sort,needs_review) select id,'layers-and-blend-modes','Layers and blend modes','Photo Studio (Pro)',10,'Combine images like a pro with layers, opacity and blend modes.',array['Switch Photo Studio to Pro.','Place a second picture as a layer (Layer → Place picture).','Change its blend mode (Multiply, Screen, Overlay) and opacity.','Duplicate layers with Ctrl+J and reorder them.']::text[],'Blend two photos into one image with a blend mode.','/photo-studio','Open Photo Studio',true,1,true from public.courses where slug='pro-photo-and-layout' on conflict (course_id,slug) do nothing;
insert into public.course_lessons (course_id,slug,title,tool,minutes,intro,steps,task,try_href,try_label,visible,sort,needs_review) select id,'selections-and-lasso','Selections and lasso','Marquee, Lasso & Select subject',10,'Edit only part of a photo with selections.',array['Use the Marquee (M) for rectangles and ellipses.','Use the Lasso (L): click points around an area, then click the first point or press Enter to close it.','Hold Shift to add to a selection, Alt to subtract, Shift+Alt to keep only the overlap.','Adjust or filter only the selected area, then Deselect.']::text[],'Select one area of a photo and change only its colour.','/photo-studio','Open Photo Studio',true,2,true from public.courses where slug='pro-photo-and-layout' on conflict (course_id,slug) do nothing;
insert into public.course_lessons (course_id,slug,title,tool,minutes,intro,steps,task,try_href,try_label,visible,sort,needs_review) select id,'retouching','Retouching','Healing, dodge, burn, sharpen',10,'Clean up blemishes and guide the eye with light.',array['Use the Healing brush (J) on spots and small objects.','Dodge (O) to brighten and Burn to darken areas.','Sharpen eyes and details lightly.','Compare with Before to keep it natural.']::text[],'Retouch a portrait or remove an unwanted object.','/photo-studio','Open Photo Studio',true,3,true from public.courses where slug='pro-photo-and-layout' on conflict (course_id,slug) do nothing;
insert into public.course_lessons (course_id,slug,title,tool,minutes,intro,steps,task,try_href,try_label,visible,sort,needs_review) select id,'clean-up-remove-unwanted-content-and-pages','Clean up: remove unwanted content and pages','Layers, Pages & Delete',6,'Professional files have nothing hidden or left over.',array['Open Layers and delete hidden or unused items.','Remove empty or duplicate pages in Pages.','Check that every photo is sharp enough for its size.','Rename the design clearly before sharing.']::text[],'Clean a design so it has no unused layers or empty pages.','/templates','Open a template',true,4,true from public.courses where slug='pro-photo-and-layout' on conflict (course_id,slug) do nothing;
insert into public.course_lessons (course_id,slug,title,tool,minutes,intro,steps,task,try_href,try_label,visible,sort,needs_review) select id,'multi-page-documents','Multi-page documents','Pages & consistent styles',12,'Brochures and decks need consistent spacing, type and colour across pages.',array['Set a grid: same margins on every page.','Use the same two fonts and a limited colour palette.','Duplicate a finished page to keep styles consistent.','Export all pages to one PDF.']::text[],'Build a 4-page document with consistent styles.','/create','Start a design',true,5,true from public.courses where slug='pro-photo-and-layout' on conflict (course_id,slug) do nothing;
insert into public.course_lessons (course_id,slug,title,tool,minutes,intro,steps,task,try_href,try_label,visible,sort,needs_review) select id,'design-from-a-blank-page','Design from a blank page','Composition & hierarchy',12,'Put it all together: hierarchy, contrast, alignment and white space.',array['Decide the one message people must see first.','Make it biggest; group the details; leave breathing space.','Limit yourself to two fonts and three colours.','Check it at small size — can you still read the main message?']::text[],'Design a poster from a blank page without using a template.','/create','Start a blank design',true,6,true from public.courses where slug='pro-photo-and-layout' on conflict (course_id,slug) do nothing;
